'@ | ConvertFrom-Json
function Get-BytesHash([byte[]]$Bytes) {
    $Sha = [System.Security.Cryptography.SHA256]::Create()
    try { return [BitConverter]::ToString($Sha.ComputeHash($Bytes)).Replace('-', '').ToLowerInvariant() }
    finally { $Sha.Dispose() }
}
function Get-PathHash([string]$Path) {
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}
function ConvertFrom-Hex([string]$Value) {
    $Bytes = [byte[]]::new([int]($Value.Length / 2))
    for ($i = 0; $i -lt $Bytes.Length; $i++) {
        $Bytes[$i] = [Convert]::ToByte($Value.Substring($i * 2, 2), 16)
    }
    return ,$Bytes
}
$GameRoot = (Resolve-Path -LiteralPath $GameRoot).ProviderPath
$BackupRoot = Join-Path $GameRoot 'FPS_Original_Backup'
$Plan = @()
$Installed = 0
foreach ($Item in $PatchData) {
    $Target = Join-Path $GameRoot $Item.path
    $Backup = Join-Path $BackupRoot $Item.path
    if (-not (Test-Path -LiteralPath $Target -PathType Leaf)) {
        Write-Host "$($Item.path): Not installed"
        continue
    }
    $Installed++
    $Current = [System.IO.File]::ReadAllBytes($Target)
    $Hash = Get-BytesHash $Current
    if ($Hash -ne $Item.original -and $Hash -ne $Item.patched) {
        throw "Unsupported executable version: $Target (SHA-256: $Hash)"
    }
    if (Test-Path -LiteralPath $Backup) {
        if ((Get-PathHash $Backup) -ne $Item.original) { throw "Invalid original backup: $Backup" }
    } elseif ($Hash -eq $Item.patched) {
        throw "Original backup missing: $Backup"
    }
    $State = if ($Hash -eq $Item.patched) { 'Adaptive FPS' } else { 'Original' }
    Write-Host "$($Item.path): $State"
    if ($Restore) {
        if ($Hash -eq $Item.original) { continue }
        $NewBytes = [System.IO.File]::ReadAllBytes($Backup)
        $Expected = $Item.original
    } else {
        if ($Hash -eq $Item.patched) { continue }
        if ($Current.Length -ne $Item.before_length) { throw "Invalid file length: $Target" }
        $NewBytes = [byte[]]::new([int]$Item.after_length)
        [Buffer]::BlockCopy($Current, 0, $NewBytes, 0, $Current.Length)
        $BoundSource = [int]$Item.bound_src
        $BoundDestination = [int]$Item.bound_dst
        $BoundLength = [int]$Item.bound_length
        if ($BoundSource -lt 0 -or $BoundDestination -lt 0 -or $BoundLength -lt 0 -or $BoundSource + $BoundLength -gt $Current.Length -or $BoundDestination + $BoundLength -gt $Current.Length) {
            throw "Invalid bound import table: $Target"
        }
        [Buffer]::BlockCopy($Current, $BoundSource, $NewBytes, $BoundDestination, $BoundLength)
        foreach ($Edit in $Item.edits) {
            $Offset = [int]$Edit[0]
            $Replacement = ConvertFrom-Hex $Edit[1]
            if ($Offset -lt 0 -or $Offset + $Replacement.Length -gt $Current.Length) {
                throw "Invalid patch offset: $Target"
            }
            [Buffer]::BlockCopy($Replacement, 0, $NewBytes, $Offset, $Replacement.Length)
        }
        $Prefix = [Convert]::FromBase64String($Item.prefix)
        $Suffix = [Convert]::FromBase64String($Item.suffix)
        $PdataOffset = [int]$Item.pdata_offset
        $PdataLength = [int]$Item.pdata_length
        if ($PdataOffset -lt 0 -or $PdataLength -lt 0 -or $PdataOffset + $PdataLength -gt $Current.Length) {
            throw "Invalid exception table: $Target"
        }
        if ($Current.Length + $Prefix.Length + $PdataLength + $Suffix.Length -ne $NewBytes.Length) {
            throw "Invalid output length: $Target"
        }
        [Buffer]::BlockCopy($Prefix, 0, $NewBytes, $Current.Length, $Prefix.Length)
        [Buffer]::BlockCopy($Current, $PdataOffset, $NewBytes, $Current.Length + $Prefix.Length, $PdataLength)
        [Buffer]::BlockCopy($Suffix, 0, $NewBytes, $Current.Length + $Prefix.Length + $PdataLength, $Suffix.Length)
        $Expected = $Item.patched
    }
    if ((Get-BytesHash $NewBytes) -ne $Expected) { throw "Output verification failed: $Target" }
    $Plan += [pscustomobject]@{
        Item = $Item
        Target = $Target
        Backup = $Backup
        Current = $Hash
        NewBytes = $NewBytes
        Expected = $Expected
        Temporary = $null
        Previous = $null
        Replaced = $false
    }
}
if ($Installed -eq 0) { throw "No supported games found in $GameRoot" }
if ($Check) { Write-Host 'Verification complete. No files changed.'; return }
if ($Plan.Count -eq 0) { Write-Host 'No changes needed.'; return }
$RunningNames = @($Plan | ForEach-Object { [System.IO.Path]::GetFileNameWithoutExtension($_.Item.path) })
$Running = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $RunningNames -contains $_.ProcessName })
if ($Running.Count -gt 0) { throw 'Close all classic games before continuing.' }
if (-not $Restore) {
    foreach ($Entry in $Plan) {
        [void][System.IO.Directory]::CreateDirectory((Split-Path -Parent $Entry.Backup))
        if (-not (Test-Path -LiteralPath $Entry.Backup)) {
            [System.IO.File]::Copy($Entry.Target, $Entry.Backup, $false)
        }
        if ((Get-PathHash $Entry.Backup) -ne $Entry.Item.original) {
            throw "Backup verification failed: $($Entry.Backup)"
        }
    }
}
try {
    foreach ($Entry in $Plan) {
        if ((Get-PathHash $Entry.Target) -ne $Entry.Current) { throw "File changed during operation: $($Entry.Target)" }
        $Entry.Temporary = Join-Path (Split-Path -Parent $Entry.Target) ('.adaptive-fps-' + [Guid]::NewGuid().ToString('N') + '.tmp')
        $Entry.Previous = $Entry.Temporary + '.previous'
        [System.IO.File]::WriteAllBytes($Entry.Temporary, $Entry.NewBytes)
        if ((Get-PathHash $Entry.Temporary) -ne $Entry.Expected) { throw "Temporary file verification failed: $($Entry.Target)" }
    }
    foreach ($Entry in $Plan) {
        if ((Get-PathHash $Entry.Target) -ne $Entry.Current) { throw "File changed during operation: $($Entry.Target)" }
        [System.IO.File]::Replace($Entry.Temporary, $Entry.Target, $Entry.Previous)
        $Entry.Replaced = $true
        if ((Get-PathHash $Entry.Target) -ne $Entry.Expected) { throw "Final verification failed: $($Entry.Target)" }
        Write-Host "OK: $($Entry.Item.path)" -ForegroundColor Green
    }
} catch {
    $Failure = $_
    for ($i = $Plan.Count - 1; $i -ge 0; $i--) {
        $Entry = $Plan[$i]
        if ($Entry.Replaced -and (Test-Path -LiteralPath $Entry.Previous)) {
            try {
                if ((Get-PathHash $Entry.Previous) -ne $Entry.Current) { throw 'Previous file hash mismatch.' }
                $Rollback = $Entry.Previous + '.rollback'
                [System.IO.File]::Replace($Entry.Previous, $Entry.Target, $Rollback)
                if ((Get-PathHash $Entry.Target) -ne $Entry.Current) { throw 'Rollback verification failed.' }
                if (Test-Path -LiteralPath $Rollback) { Remove-Item -LiteralPath $Rollback -Force }
                $Entry.Replaced = $false
            } catch {
                Write-Warning "Could not roll back $($Entry.Target): $_"
            }
        }
    }
    throw $Failure
} finally {
    foreach ($Entry in $Plan) {
        if ($Entry.Temporary -and (Test-Path -LiteralPath $Entry.Temporary)) {
            Remove-Item -LiteralPath $Entry.Temporary -Force
        }
    }
}
foreach ($Entry in $Plan) {
    if ($Entry.Previous -and (Test-Path -LiteralPath $Entry.Previous)) {
        Remove-Item -LiteralPath $Entry.Previous -Force
    }
}
if ($Restore) { Write-Host 'Original games restored.' -ForegroundColor Green }
else { Write-Host 'Adaptive FPS installed. Start the games normally.' -ForegroundColor Green }
Write-Host "Original backups: $BackupRoot"
